import { works } from '../data/work'

// Builds { slug -> { srcSet, fallback } } maps from the optimized asset folders
// generated by scripts/optimize-images.mjs, so components never hand-wire file paths.
const workWebp = import.meta.glob('../assets/work/*.webp', { eager: true, query: '?url', import: 'default' })
const workJpg = import.meta.glob('../assets/work/*.jpg', { eager: true, query: '?url', import: 'default' })
const profileWebp = import.meta.glob('../assets/profile/*.webp', { eager: true, query: '?url', import: 'default' })
const profileJpg = import.meta.glob('../assets/profile/*.jpg', { eager: true, query: '?url', import: 'default' })

function buildSet(webpModules, jpgModules) {
  const bySlug = {}

  for (const [filePath, url] of Object.entries(webpModules)) {
    const name = filePath.split('/').pop().replace('.webp', '')
    const match = name.match(/^(.+)-(\d+)$/)
    if (!match) continue
    const [, slug, width] = match
    bySlug[slug] ??= { widths: [], fallback: '' }
    bySlug[slug].widths.push({ width: Number(width), url })
  }

  for (const [filePath, url] of Object.entries(jpgModules)) {
    const slug = filePath.split('/').pop().replace('.jpg', '')
    bySlug[slug] ??= { widths: [], fallback: '' }
    bySlug[slug].fallback = url
  }

  const result = {}
  for (const [slug, { widths, fallback }] of Object.entries(bySlug)) {
    widths.sort((a, b) => a.width - b.width)
    result[slug] = {
      srcSet: widths.map(({ url, width }) => `${url} ${width}w`).join(', '),
      src: fallback || widths[widths.length - 1]?.url,
      widths: widths.map((w) => w.width),
      // Ascending [{ width, url }]. <img> picks from srcSet on its own; this is
      // for the places that have to name one specific variant — see
      // heroSlideImages below.
      sources: widths,
    }
  }
  return result
}

export const workImages = buildSet(workWebp, workJpg)
export const profileImages = buildSet(profileWebp, profileJpg)

// Deliberately a mid-size variant, not the JPEG fallback these used to point
// at: the LCD is a small panel on a 3D model, so a 2200px/1MB source is ~5x the
// bytes for no visible gain — and the first of these gates the Preloader, where
// that difference is the whole reveal. WebP is safe here because the 3D path is
// gated to desktop/fine-pointer devices anyway.
const SLIDE_WIDTH = 1080

function variantAtLeast(image, minWidth) {
  if (!image?.sources?.length) return image?.src
  const match = image.sources.find(({ width }) => width >= minWidth)
  return (match ?? image.sources[image.sources.length - 1]).url
}

// The photos the Hero's 3D camera LCD cycles through — the only work images
// that can appear before any scrolling. Each carries two forms because it has
// two consumers with opposite needs: `texture` is the small variant the 3D
// panel samples, while srcSet/src are the full responsive set the DOM overlay
// uses when that same photo is crossfaded fullscreen on click-to-enter.
export const heroSlides = works
  .slice(0, 5)
  .map((work) => {
    const image = workImages[work.slug]
    if (!image) return null
    return {
      texture: variantAtLeast(image, SLIDE_WIDTH),
      srcSet: image.srcSet,
      src: image.src,
    }
  })
  .filter(Boolean)

// Just the texture URLs — what CameraScene loads and what the Preloader waits
// on, shared from here so the two can't drift apart.
export const heroSlideImages = heroSlides.map((slide) => slide.texture)
